@bead("complete_days", strand="ridge", after=("daily_profiles",),
      title="Filter Complete 24h Days",
      io=("3,229 daily", "complete 24h days"),
      tokens=("DST", "October 30", "complete days", "24h"),
      explains="Keep only days with 24 distinct clock hours, excluding daylight-saving days.")
def complete_days(profiles: dict[date, dict[str, Any]]) -> pd.DataFrame:
    days = sorted(d for d, p in profiles.items() if p["raw_hour_count"] == 24)
    return pd.DataFrame(np.vstack([profiles[d]["load_24"] for d in days]),
                        index=pd.DatetimeIndex(days), columns=range(24))

@bead("errors", strand="evaluate",
      title="MAE & RMSE Error Metric",
      io=("actual, forecast MW", "MAE & RMSE in MW"),
      tokens=("MAE", "RMSE", "residual", "metrics", "MW"),
      explains="Score a forecast by mean absolute error and root mean squared error in MW.")
def errors(actual, forecast) -> dict[str, float]:
    residual = np.asarray(forecast, dtype=np.float64).ravel() - np.asarray(actual, dtype=np.float64).ravel()
    return {"mae_mw": float(np.abs(residual).mean()), "rmse_mw": float(np.sqrt(np.mean(residual ** 2)))}

@bead("ridge_reference", strand="ridge", after=("hourly_examples",),
      title="Cholesky Reference Fit",
      io=("train scaled", "Cholesky w* (12)"),
      tokens=("Cholesky", "exact optimum", "StandardScaler", "Ridge", "reference"),
      explains="Standardize on training hours and solve Ridge exactly with Cholesky.")
def ridge_reference(ex: HourlyExamples, alpha: float = SELECTED_ALPHA) -> ScaledProblem:
    train = ex.split("train")
    scaler = StandardScaler().fit(ex.x[train])
    scaled = scaler.transform(ex.x)
    return ScaledProblem(scaler, scaled, Ridge(alpha=alpha, solver="cholesky").fit(scaled[train], ex.y[train]))

@bead("score_table", strand="evaluate", after=("shared_cohort", "errors"),
      title="Rank All 7 Forecasts",
      io=("7,224 hrs × 7 models", "ranked MAE/RMSE table"),
      tokens=("ranking", "1,691.65", "1,786.59", "2,294.08", "2,351.17", "2,393.23", "Table 8"),
      explains="Rank every forecast by MAE and RMSE on the same hours.")
def score_table(frame: pd.DataFrame, models=None) -> pd.DataFrame:
    rows = [{"model": m, "hours": len(frame), **errors(frame["actual"], frame[m])} for m in _models(frame, models)]
    return pd.DataFrame(rows).sort_values("mae_mw", ignore_index=True)

@bead("high_load", strand="evaluate", after=("shared_cohort",),
      title="Error at Top 10% and Peak Hours",
      io=("top 10% = 723 hrs", "peak 2026-07-22 17:00"),
      tokens=("peak", "91.1 GW", "2026-07-22", "top 10%", "723 hours", "high load", "Table 9"),
      explains="Score the top tenth of hours by measured load, and the error at the single highest hour.")
def high_load(frame: pd.DataFrame, models=None, share: float = 0.1) -> pd.DataFrame:
    n = int(np.ceil(share * len(frame)))
    top = frame.nlargest(n, "actual")
    peak = frame.loc[frame["actual"].idxmax()]
    return pd.DataFrame([{"model": m, "top_hours": n, "top_mae_mw": float((top[m] - top["actual"]).abs().mean()),
                          "peak_timestamp": peak["timestamp"], "peak_error_mw": float(peak[m] - peak["actual"])}
                         for m in _models(frame, models)])

@bead("mae_by_hour", strand="evaluate", after=("shared_cohort",),
      title="Error by Forecast Hour (0–23)",
      io=("7,224 hrs", "24-hour MAE curve"),
      tokens=("horizon", "hour of day", "555.73", "2,143.70", "lead hour"),
      explains="Average absolute error separately for each of the 24 forecast hours.")
def mae_by_hour(frame: pd.DataFrame, models=None) -> pd.DataFrame:
    cols = _models(frame, models)
    return frame[cols].sub(frame["actual"], axis=0).abs().groupby(frame["timestamp"].dt.hour).mean().rename_axis("hour")

@bead("seasonal_mae", strand="evaluate", after=("shared_cohort",),
      title="Seasonal Error Breakdown",
      io=("4 season blocks", "Jun-Aug 1,525.67 MW"),
      tokens=("seasonal", "summer", "Jun-Aug", "1,525.67", "Mar-May", "Table 10"),
      explains="Average absolute error within each block of months.")
def seasonal_mae(frame: pd.DataFrame, models=None) -> pd.DataFrame:
    cols, month = _models(frame, models), frame["timestamp"].dt.month
    rows = []
    for block, months in SEASONS.items():
        part = frame[month.isin(months)]
        rows.append({"months": block, "hours": len(part),
                     **{m: float((part[m] - part["actual"]).abs().mean()) for m in cols}})
    return pd.DataFrame(rows)

@bead("daily_wins", strand="evaluate", after=("shared_cohort",),
      title="Count Days Each Model Wins",
      io=("301 paired days", "LSTM beats Ridge 214/301"),
      tokens=("214", "71%", "daily wins", "head-to-head", "LSTM vs Ridge"),
      explains="Count the days on which one forecast's daily MAE beats another's.")
def daily_wins(frame: pd.DataFrame, model: str, rival: str) -> dict:
    day = frame["timestamp"].dt.normalize()
    daily = frame[[model, rival]].sub(frame["actual"], axis=0).abs().groupby(day).mean()
    wins = int((daily[model] < daily[rival]).sum())
    return {"model": model, "rival": rival, "days": len(daily), "wins": wins, "share": wins / len(daily)}

@bead("svr_fit", strand="svr", after=("svr_sample",),
      title="RBF-Kernel SVR Fit",
      io=("6,000 × 12", "RBF-SVR model"),
      tokens=("RBF", "SVR", "kernel", "C=10", "epsilon=0.1", "gamma=0.01"),
      explains="Fit an RBF-kernel SVR with standardized inputs and target.")
def svr_fit(x: np.ndarray, y: np.ndarray, C, epsilon, gamma) -> TransformedTargetRegressor:
    model = TransformedTargetRegressor(
        regressor=Pipeline([("scaler", StandardScaler()),
                            ("svr", SVR(kernel="rbf", C=C, epsilon=epsilon, gamma=gamma, cache_size=500))]),
        transformer=StandardScaler(),
    )
    return model.fit(x, y)

@bead("ffn_bundle", strand="ffn", after=("day_ahead_features",),
      title="Load Step 0 FFN Bundle",
      io=("ercot_step0_features.npz", "X(3221×67), Y(3221×24)"),
      tokens=("FFN", "67 features", "npz", "Step 0"),
      explains="Load the 67-input, 24-target day-ahead arrays that Step 0 built.")
def ffn_bundle() -> dict[str, np.ndarray]:
    if FEATURES_NPZ_PATH.is_file():
        with np.load(FEATURES_NPZ_PATH, allow_pickle=False) as cache:
            return {k: cache[k] for k in _KEYS}
    from .s01_system_data import day_ahead_features, load_system_data
    bundle = day_ahead_features(load_system_data())
    return {k: bundle[k] for k in _KEYS}

@bead("ffn_targets", strand="ffn", after=("ffn_bundle",),
      title="Standardize FFN Targets",
      io=("Y in MW", "per-hour z-scored Y"),
      tokens=("target scaling", "float64", "FFN", "train stats"),
      explains="Standardize each of the 24 target hours with its training mean and spread.")
def ffn_targets(bundle: dict[str, np.ndarray]) -> FFNProblem:
    splits = bundle["splits"]
    masks = {s: splits == s for s in ("train", "val", "test")}
    x = torch.from_numpy(bundle["X_scaled"].astype(np.float64))
    y_mw = torch.from_numpy(bundle["Y"].astype(np.float64))
    mean = y_mw[masks["train"]].mean(dim=0)
    sd = y_mw[masks["train"]].std(dim=0, correction=0)
    return FFNProblem(x, y_mw, (y_mw - mean) / sd, mean, sd, masks, bundle["target_dates"])

@bead("ffn_network", strand="ffn",
      title="67 → 64 → 24 ReLU Network",
      io=("seed=42", "67 → 64 → 24 ReLU"),
      tokens=("feed-forward", "FFN", "ReLU", "neural network", "seed 42", "67→64→24"),
      explains="Create the 67 → 64 → 24 ReLU network from a fixed seed so both optimizers start identically.")
def ffn_network(seed: int = SEED) -> nn.Sequential:
    torch.manual_seed(seed)
    return nn.Sequential(nn.Linear(67, 64), nn.ReLU(), nn.Linear(64, 24)).double()

@bead("ffn_forecast", strand="ffn", after=("ffn_train",),
      title="FFN Test Forecast",
      io=("best weights + test X", "306 × 24 MW forecast"),
      tokens=("FFN", "1,786.59", "2,083.21", "test forecast"),
      explains="Predict a split's 24-hour profiles and convert back to MW.")
@torch.no_grad()
def ffn_forecast(p: FFNProblem, weights: dict, split: str = "test") -> np.ndarray:
    model = ffn_network()
    model.load_state_dict(weights)
    return (model(p.x[p.masks[split]]) * p.target_sd + p.target_mean).numpy()

@bead("day_grid", strand="lstm", after=("daily_profiles",),
      title="Continuous 24h Day Grid",
      io=("3,229 daily", "3,230 × 24 continuous"),
      tokens=("October 30", "day grid", "missing day", "LSTM"),
      explains="Lay every calendar day on a 24-slot grid; a missing day borrows last week's hours as input only.")
def day_grid(profiles: dict[date, dict[str, Any]]) -> DayGrid:
    first, last = min(profiles), max(profiles)
    days = pd.date_range(first, last, freq="D")
    load = np.empty((len(days), 24))
    ok = np.zeros(len(days), dtype=bool)
    uri = np.zeros(len(days), dtype=bool)
    for i, d in enumerate(days.date):
        if d in profiles:
            load[i], ok[i], uri[i] = profiles[d]["load_24"], True, profiles[d]["is_uri"]
        else:
            load[i] = load[i - 7]
    return DayGrid(days, load, ok, uri, np.array([day_split(d) for d in days.date]))

@bead("lstm_tensors", strand="lstm", after=("lstm_samples",),
      title="Uri Exclusion & Tensor Split",
      io=("sequences + Uri mask", "2,156 train / 731 val / 307 test"),
      tokens=("Winter Storm Uri", "Uri exclusion", "21 windows", "2,156", "tensors", "leakage"),
      explains="Drop training samples that touch Winter Storm Uri, fit the scaler on training days, and build tensors.")
def lstm_tensors(grid: DayGrid, cal: Calendar, cfg: dict, exclude_uri_train: bool = True) -> dict[str, Any]:
    S = lstm_samples(grid, cal, cfg["lookback"], cfg["level_days"])
    train = (S["split"] == "train") & ~(S["uri"] if exclude_uri_train else np.zeros_like(S["uri"]))
    scaler = Scaler().fit(S, train)
    seq, static, y = scaler.transform(S)
    masks = {"train": train, "val": S["split"] == "val", "test": S["split"] == "test"}
    tensors = {k: tuple(torch.tensor(a[m]) for a in (seq, static, y)) for k, m in masks.items()}
    return dict(S=S, scaler=scaler, masks=masks, tensors=tensors, n_seq=seq.shape[2], n_static=static.shape[1])

@bead("lstm_network", strand="lstm", after=("lstm_tensors",),
      title="2-Layer LSTM Architecture",
      io=("n_seq=29, n_static=11", "70,424-param 2-layer LSTM"),
      tokens=("LSTM", "64 hidden", "2 layers", "70,424", "dropout 0.2"),
      explains="Build the LSTM forecaster sized to the input tensors.")
def lstm_network(data: dict, cfg: dict = CONFIG) -> LSTMForecaster:
    return LSTMForecaster(data["n_seq"], data["n_static"], cfg["hidden"], cfg["layers"],
                          cfg["dropout"], cfg["head_units"])

@bead("lstm_forecast", strand="lstm", after=("lstm_train", "lstm_load_weights"),
      title="Rescale LSTM Forecast to MW",
      io=("std pred × 7d level", "24h MW forecast"),
      tokens=("LSTM", "forecast", "MW", "unscale"),
      explains="Predict standardized relative load, then multiply back by each day's 7-day level to get MW.")
def lstm_forecast(model, data: dict, split: str) -> np.ndarray:
    seq, static, _ = data["tensors"][split]
    return data["scaler"].to_mw(predict_std(model, seq, static), data["S"]["level"][data["masks"][split]])

@bead("lstm_ensemble", strand="lstm", after=("lstm_forecast",),
      title="3-Seed LSTM Ensemble",
      io=("3 seeds (42, 7, 2026)", "1,691.65 MW test MAE"),
      tokens=("ensemble", "1,691.65", "2,501.63", "1,621.87", "best model", "LSTM", "3 seeds"),
      explains="Average the MW forecasts of seeds 42, 7 and 2026.")
def lstm_ensemble(models, data: dict, split: str) -> np.ndarray:
    return np.mean([lstm_forecast(m, data, split) for m in models], axis=0)
